import com.sun.jdi.*;import com.sun.jdi.connect.*;import com.sun.jdi.event.*;import com.sun.jdi.request.*;import java.util.*;
public class JdiFlash{
 static Method find(ReferenceType t,String n,String s){for(Method m:t.methodsByName(n))if(m.signature().equals(s))return m;return null;}
 static void ex(InvocationException ie){ObjectReference e=ie.exception();System.out.println("EX "+e.referenceType().name());try{Field f=e.referenceType().fieldByName("detailMessage");if(f!=null)System.out.println(" msg="+e.getValue(f));}catch(Throwable t){}}
 public static void main(String[] a)throws Exception{AttachingConnector conn=null;for(AttachingConnector c:Bootstrap.virtualMachineManager().attachingConnectors())if(c.name().equals("com.sun.jdi.SocketAttach"))conn=c;Map<String,Connector.Argument> ca=conn.defaultArguments();ca.get("hostname").setValue("localhost");ca.get("port").setValue("8700");ca.get("timeout").setValue("5000");VirtualMachine vm=conn.attach(ca);
 try{ReferenceType svc=vm.classesByName("com.cvte.factory.service.MainService").get(0);Method on=find(svc,"onStartCommand","(Landroid/content/Intent;II)I");BreakpointRequest bp=vm.eventRequestManager().createBreakpointRequest(on.location());bp.setSuspendPolicy(EventRequest.SUSPEND_EVENT_THREAD);bp.enable();Thread t=new Thread(()->{try{Thread.sleep(1200);new ProcessBuilder("adb","-s","<TV_IP>:5555","shell","am","startservice","-n","com.cvte.factory.service/.MainService","-a","cvte.factory.intent.action.APIInit").inheritIO().start().waitFor();}catch(Exception e){e.printStackTrace();}});t.start();vm.resume();EventSet es=vm.eventQueue().remove(15000);ThreadReference thr=null;if(es!=null)for(Event ev:es)if(ev instanceof BreakpointEvent)thr=((BreakpointEvent)ev).thread();if(thr==null){System.out.println("no bp");vm.resume();return;}
 ClassType os=(ClassType)vm.classesByName("android.system.Os").get(0);Method open=find(os,"open","(Ljava/lang/String;II)Ljava/io/FileDescriptor;");ObjectReference fd=(ObjectReference)os.invokeMethod(thr,open,Arrays.asList(vm.mirrorOf("/dev/mik!flash"),vm.mirrorOf(2),vm.mirrorOf(0)),0);System.out.println("fd="+fd);
 ClassType bbC=(ClassType)vm.classesByName("java.nio.ByteBuffer").get(0);Method alloc=find(bbC,"allocateDirect","(I)Ljava/nio/ByteBuffer;");ObjectReference bb=(ObjectReference)bbC.invokeMethod(thr,alloc,Collections.singletonList(vm.mirrorOf(160)),0);ClassType ibC=(ClassType)vm.classesByName("java.nio.IntBuffer").get(0);ObjectReference ib=(ObjectReference)bb.invokeMethod(thr,find(bbC,"asIntBuffer","()Ljava/nio/IntBuffer;"),Collections.emptyList(),0);
 Method put=find(ibC,"put","(I)Ljava/nio/IntBuffer;");for(int i=0;i<40;i++) ib.invokeMethod(thr,put,Collections.singletonList(vm.mirrorOf(0)),0);
 // rewind
 Method rew=find(ibC,"rewind","()Ljava/nio/Buffer;");ib.invokeMethod(thr,rew,Collections.emptyList(),0);
 Method ioctl=find(os,"ioctlInt","(Ljava/io/FileDescriptor;ILjava/nio/IntBuffer;)I");System.out.println("ioctl="+ioctl);
 for(long cmd: new long[]{0xc08c2d02L,0xc08c2d03L,0xc08c2d04L,0xc0382d0bL}){try{int r=((IntegerValue)os.invokeMethod(thr,ioctl,Arrays.asList((Value)fd,vm.mirrorOf((int)cmd),(Value)ib),0)).value();System.out.println(String.format("cmd=%08x r=%d",cmd,r));}catch(InvocationException ie){System.out.print(String.format("cmd=%08x ",cmd));ex(ie);}}
 bp.disable();vm.resume();}finally{vm.dispose();}}
}
